 void connect(){connect(false);}
 void connect(boolean automatic){if(automatic&&SystemClock.elapsedRealtime()<nextConnectAt)return;if(editing||busy){toast("请先完成当前操作");return;}if(origin.isEmpty()){page="设备";draw();return;}final String destination=origin,expectedIdentity=deviceID;final String[] endpoint={destination};final JSONObject[] s={null};final byte[][] b={null};work(automatic?"自动重连":"读取设备最新内容",()->{try{DeviceLocator.Connection found=locator.read(destination,expectedIdentity);s[0]=found.state;endpoint[0]=found.origin;b[0]=DeskApi.base(endpoint[0]);}catch(Exception e){ui.post(()->{if(destination.equals(origin)){connected=false;connectFailures++;nextConnectAt=SystemClock.elapsedRealtime()+SyncPolicy.retryDelay(connectFailures);}});throw e;}},()->{if(!destination.equals(origin)||!deviceID.equals(expectedIdentity))return;origin=endpoint[0];if(DeviceLocator.valid(s[0].optString("device_id")))deviceID=s[0].optString("device_id");connectFailures=0;nextConnectAt=0;connected=true;health.contacted(origin);remote=s[0];base=b[0];if(dirty&&!sameTasks(tasks,remote.optJSONArray("tasks"))){resolvingConflict=true;automaticRetryAllowed=false;queuedSync=false;queuedFull=false;queuedInfo=false;message="本机有待同步内容，请选择保留哪份清单";AlertDialog dialog=new AlertDialog.Builder(this).setTitle("两端清单不同").setMessage("本机有未同步更改，设备也有自己的内容。请选择来源，避免旧清单覆盖新清单。").setNegativeButton("采用设备清单",(d,w)->{tasks=DeskModel.copy(remote.optJSONArray("tasks"));dirty=false;automaticRetryAllowed=true;editRevision.acknowledge(editRevision.snapshot());message="已采用设备最新清单";persist();draw();}).setPositiveButton("保留本机，稍后同步",(d,w)->{message="已保留本机内容，点击同步后才覆盖设备";draw();}).create();dialog.setOnDismissListener(d->{resolvingConflict=false;updateStatus();capture.drain();});dialog.show();}else{tasks=DeskModel.copy(remote.optJSONArray("tasks"));dirty=false;adoptScreen(remote);automaticRetryAllowed=!screenPending;message=screenPending?"已读取设备，卡片更改请核对后手动同步":"已读取设备最新内容";}scheduleCheck();});}
 void adoptScreen(JSONObject state){if(screenPending||dirty)return;try{cfg=ScreenData.adopt(cfg,state);if(!page.equals("选择场景"))screen.selected=cfg.optString("scene","work");}catch(Exception e){message=e.getMessage();}}
 boolean sameTasks(JSONArray a,JSONArray b){return SyncPolicy.sameTasks(a,b);}
 boolean sameProfile(JSONObject a,JSONObject b){return ScreenSync.sameProfile(a,b);}
 void sync(boolean full,boolean info){if(resolvingConflict){toast("请先选择清单来源");return;}automaticRetryAllowed=true;if(busy){queuedSync=true;queuedFull|=full;queuedInfo|=info;message="更改已保存在手机，当前操作完成后自动同步";persist();redrawWhenIdle();return;}if((full||info)&&cfg.optBoolean("stockConfigured")&&cfg.optJSONArray("stocks")!=null&&cfg.optJSONArray("stocks").length()>0&&quotes.length()!=cfg.optJSONArray("stocks").length()){toast("请先刷新行情，避免空数据覆盖屏幕现有行情");return;}if(!connected||base==null||remote==null){message="更改已保存在手机，连接后再同步";persist();redrawWhenIdle();return;}if(!full&&remote.optBoolean("needs_full")){message="设备重启后需明确应用布局一次，更改已保存在手机";draw();return;}final long sentRevision=editRevision.snapshot();final String destination=origin;final JSONArray snapshot=DeskModel.copy(tasks);final JSONObject conf=DeskModel.copy(cfg),state=DeskModel.copy(remote);final JSONArray recorded=DeskModel.copy(completions);final byte[] old=base.clone();final JSONObject w=weather==null?null:DeskModel.copy(weather);final JSONArray q=DeskModel.copy(quotes);final byte[][] result={null};final JSONObject[] metadata={null};work(full?"正在应用布局并全刷一次":"正在局部同步",()->{try{JSONObject latest=DeskApi.state(destination);DeviceLocator.verify(deviceID,latest);if(!sameTasks(state.optJSONArray("tasks"),latest.optJSONArray("tasks"))||!state.optString("layout_id").equals(latest.optString("layout_id"))||!sameProfile(state,latest))throw new Exception("设备内容已被另一端修改，请先重新连接读取，未覆盖设备");String id=full?DeskModel.layoutId(conf):state.getString("layout_id");byte[] currentBase=full?old:DeskApi.base(destination);boolean matches=DeskModel.layoutId(conf).equals(id);JSONObject actual=DeskExtras.deviceConfig(ScreenSync.actual(conf,state,full));JSONObject renderConfig=ScreenData.renderConfig(actual,recorded,Instant.now());DeskRenderer renderer=new DeskRenderer(currentBase,snapshot,renderConfig,w,q);if(full)renderer.full(id);else{renderer.tasks(id);if(!DeskModel.kind(id).equals("calendar")||id.endsWith(".phone"))renderer.clock();if(info)renderer.infoPatch(id);if(ScreenSync.patchAllowed(id,actual))renderer.cardsPatch(id);}result[0]=renderer.frame();JSONObject meta=new JSONObject().put("expected_content_key",latest.optString("content_key")).put("tasks",DeskModel.ordered(snapshot)).put("layout_id",id).put("external_layout",true).put("accent_version",full?"mojian-red-v2":state.optString("accent_version","")).put("accent_style",full?DeskModel.kind(id):state.optString("accent_style","")).put("phone_settings",actual).put("content_key",DeskModel.contentKey(snapshot.toString()+actual.toString()+ScreenData.weekCount(recorded,Instant.now())+LocalDate.now(ScreenData.ZONE)+(w==null?"":w.toString())+q.toString())).put("epoch_seconds",System.currentTimeMillis()/1000).put("updated_at",Instant.now().toString());if(meta.toString().getBytes(StandardCharsets.UTF_8).length>latest.optInt("metadata_limit",4096))throw new Exception("配置信息过长，请缩短小纸条或待办");DeskApi.commit(destination,meta,result[0],full);metadata[0]=DeskApi.state(destination);DeviceLocator.verify(deviceID,metadata[0]);if(!sameTasks(metadata[0].optJSONArray("tasks"),meta.optJSONArray("tasks"))||!metadata[0].optString("layout_id").equals(id))throw new Exception("设备已被另一端修改，请重新读取");}catch(Exception e){ui.post(()->{syncFailures++;nextRetryAt=SystemClock.elapsedRealtime()+SyncPolicy.retryDelay(syncFailures);});throw e;}},()->{syncFailures=0;nextRetryAt=0;base=result[0];remote=metadata[0];health.contacted(destination);health.received(destination);if(editRevision.acknowledge(sentRevision)){tasks=snapshot;dirty=false;if(DeskModel.layoutId(conf).equals(remote.optString("layout_id")))screenPending=false;}else{dirty=true;queuedSync=true;}lastClockMinute=System.currentTimeMillis()/60000;message=screenPending?"清单已同步，场景仍待明确应用":"已同步 · "+(full?"布局已应用":"局部更新完成");});}
 void screenChanged(){editRevision.edited();screenPending=true;persist();draw();}
 void drainQueued(){if(capture.drain())return;if(queuedSync&&!busy&&!editing&&!resolvingConflict&&connected){boolean full=queuedFull,info=queuedInfo;queuedSync=false;queuedFull=false;queuedInfo=false;ui.post(()->sync(full,info));}}
