 if(selected.equals("custom")){LinearLayout custom=card("自定义比例");EditText ratio=field(custom,"待办所占比例（40–75%）",String.valueOf(cfg.optInt("ratio",67)));ratio.setInputType(InputType.TYPE_CLASS_NUMBER);custom.addView(text("数字越大，待办区域越宽。",13,muted));}
