 void applyLayoutSelection(){if(busy){toast("正在同步，请稍后应用");return;}String chosen=stagedLayout==null?cfg.optString("layout","overview"):stagedLayout;int ratio=cfg.optInt("ratio",67);try{if(chosen.equals("custom"))ratio=Integer.parseInt(drafts.getOrDefault("布局|待办所占比例（40–75%）",String.valueOf(ratio)));if(ratio<40||ratio>75)throw new Exception();}catch(Exception e){toast("请输入40至75的比例");return;}final int value=ratio;hideKeyboard();new AlertDialog.Builder(this).setTitle("应用这套布局？").setMessage("屏幕会全刷一次，保留当前清单。之后日常内容仍使用局部更新。").setNegativeButton("再看看",null).setPositiveButton("确认应用",(d,w)->{try{cfg.put("layout",chosen).put("ratio",value).put("cardsVersion",1).put("scene",chosen.equals("pomodoro")?"focus":"work");drafts.remove("布局|待办所占比例（40–75%）");screenChanged();sync(true,true);}catch(Exception e){toast(e.getMessage());}}).show();}
