 Spinner cardSpinner(LinearLayout parent,String label,String[] labels,String[] keys,String setting){parent.addView(text(label,13,muted));Spinner spinner=new Spinner(this);spinner.setMinimumHeight(dp(48));spinner.setContentDescription(label);spinner.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,labels));for(int i=0;i<keys.length;i++)if(keys[i].equals(drafts.getOrDefault(page+"|"+setting,cfg.optString(setting))))spinner.setSelection(i);spinner.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onItemSelected(AdapterView<?> v,View view,int at,long id){drafts.put(page+"|"+setting,keys[at]);}public void onNothingSelected(AdapterView<?> v){}});parent.addView(spinner,new LinearLayout.LayoutParams(-1,-2));return spinner;}
 void searchCity(String name){if(name.isEmpty()){toast("请输入城市名称");return;}final JSONArray[] results={null};work("正在查找城市",()->results[0]=DeskApi.cities(name),()->{JSONArray a=results[0];if(a==null||a.length()==0){message="没有找到城市，原配置保留";return;}String[] labels=new String[a.length()];for(int i=0;i<a.length();i++){JSONObject j=a.optJSONObject(i);labels[i]=j.optString("name")+" · "+j.optString("admin1",j.optString("country"));}new AlertDialog.Builder(this).setTitle("选择天气城市").setItems(labels,(d,n)->{try{JSONObject j=a.getJSONObject(n);cfg.put("city",j.getString("name")).put("latitude",j.getDouble("latitude")).put("longitude",j.getDouble("longitude"));weather=null;clearDraft("城市名称");persist();message="城市已保存，请刷新天气";draw();}catch(Exception e){toast(e.getMessage());}}).show();});}
