 void refreshFeeds(boolean push){final JSONObject conf=DeskModel.copy(cfg);final JSONObject[] w={null};final JSONArray[] q={null};final List<String> errors=new ArrayList<>();work("正在获取天气和行情",()->{try{w[0]=DeskApi.weather(conf);}catch(Exception e){errors.add("天气："+e.getMessage());}try{q[0]=DeskApi.stocks(conf.getJSONArray("stocks"));}catch(Exception e){errors.add("行情："+e.getMessage());}},()->{health.weatherFailed=w[0]==null;health.stocksFailed=q[0]==null;if(w[0]!=null)weather=w[0];if(q[0]!=null)quotes=q[0];message=errors.isEmpty()?"天气和行情已更新到手机，点击同步即可上屏":String.join("；",errors)+"；保留上次有效结果";if(push&&errors.isEmpty())ui.post(()->sync(false,true));});}
 void device(){LinearLayout l=card("我的工作台");EditText address=field(l,"http://ESP32 的 IP",origin);primary(l,"连接并读取内容",()->{if(busy){toast("当前操作正在进行，请稍后再试");return;}try{origin=DeskModel.normalizeOrigin(address.getText().toString());clearDraft("http://ESP32 的 IP");persist();connect();}catch(Exception e){toast(e.getMessage());}});button(l,"蓝牙发现设备",this::scan);l.addView(text("蓝牙负责发现，内容通过同一 Wi-Fi 传输；无需访问口令。Mac 可以关闭。",14,muted));button(l,"重新读取设备画面",this::connect);l.addView(text(deviceID.isEmpty()?"连接一次新版固件后，将记住屏幕身份并自动找回地址。":"已记住屏幕 · IP变化时自动寻找同一台设备。",14,muted));button(l,"更换屏幕 / 解除绑定",()->{if(busy||polling){toast("请等待当前连接操作完成");return;}new AlertDialog.Builder(this).setTitle("解除当前屏幕绑定？").setMessage("保留本机清单，停止连接当前屏幕。之后请用蓝牙发现或填写新屏幕地址。").setNegativeButton("取消",null).setPositiveButton("解除绑定",(d,w)->{deviceID="";origin="";connected=false;remote=null;base=null;nextConnectAt=0;persist();draw();}).show();});LinearLayout about=card("墨间 Android 0.8.0");about.addView(text("已实现：待办编辑、改期、置顶、完成撤销、历史恢复、布局应用、天气和自选行情配置。\n\n已加入 DeepSeek 工具助手、确认卡片、本地提醒与可编辑偏好。已加入三种场景、独立卡片局刷、生长盆栽、倒计时、专注计时和生活画报。已加入手机日历、通勤、习惯打卡、场景收藏与模板文件分享。",14,muted));}

 void applyAgent(JSONObject p,AgentStore store)throws Exception {
  String tool=p.getString("tool");JSONObject args=p.getJSONObject("args");
  if(tool.equals("propose_memory")){JSONObject expected=p.optJSONObject("expectedMemory");String id=null;if(expected!=null){id=expected.getString("id");boolean found=false;for(int i=0;i<store.memories.length();i++)if(store.memories.getJSONObject(i).optString("id").equals(id)){found=true;if(!SyncPolicy.canonical(expected).equals(SyncPolicy.canonical(store.memories.getJSONObject(i))))throw new Exception("偏好已变化，请重新提出");}if(!found)throw new Exception("偏好已移除");}store.memories=PreferenceMemory.save(store.memories,id,args.getString("key"),args.getString("value"),p.optString("source"));store.save();return;}
  if(tool.equals("propose_reminder_settings")){ReminderScheduler.configure(this,args);return;}
  if(tool.equals("propose_layout")){if(busy||!connected||remote==null)throw new Exception("请先连接设备，等待同步结束后重新提出");if(cfg.optBoolean("stockConfigured")&&cfg.optJSONArray("stocks").length()!=quotes.length())throw new Exception("请先刷新行情，再应用布局");cfg.put("layout",args.getString("layout")).put("ratio",args.optInt("ratio",cfg.optInt("ratio",67))).put("cardsVersion",1).put("scene",args.getString("layout").equals("pomodoro")?"focus":"work");stagedLayout=null;screenChanged();sync(true,true);return;}
  if(!tool.equals("propose_task_change"))throw new Exception("不支持的操作");TaskProposal.Result result=TaskProposal.apply(tasks,history,p);tasks=result.tasks;history=result.history;changed();sync(false,false);
 }
 void scan(){if(busy){toast("当前操作正在进行，请稍后再试");return;}String[] permissions=Build.VERSION.SDK_INT>=31?new String[]{Manifest.permission.BLUETOOTH_SCAN,Manifest.permission.BLUETOOTH_CONNECT}:new String[]{Manifest.permission.ACCESS_FINE_LOCATION};for(String p:permissions)if(checkSelfPermission(p)!=PackageManager.PERMISSION_GRANTED){requestPermissions(permissions,21);return;}discovery.start();}
 boolean polling=false,foreground=false,resolvingConflict=false,automaticRetryAllowed=true,showAllHistory=false;
 int syncFailures=0;long nextRetryAt=0;
 final Map<String,String> drafts=new HashMap<>();String stagedLayout=null;
 final Runnable check=new Runnable(){public void run(){if(destroyed||!foreground)return;if(page.equals("连接与数据")&&!busy)redrawWhenIdle();if(community!=null)community.autoExchange();if(integrations!=null&&cfg.optBoolean("calendarEnabled")&&!busy&&!editing&&!(getCurrentFocus() instanceof EditText)&&!resolvingConflict&&System.currentTimeMillis()-integrations.lastCalendar>60000){integrations.refreshCalendar();}if(!connected&&!origin.isEmpty()&&!busy&&!editing&&!resolvingConflict){connect(true);}if(connected&&!busy&&!polling&&!editing&&!resolvingConflict){polling=true;final String destination=origin;final long revision=editRevision.snapshot();final JSONObject baseline=remote==null?null:DeskModel.copy(remote);final JSONArray local=DeskModel.copy(tasks);final boolean pending=dirty;worker.execute(()->{try{JSONObject latest=DeskApi.state(destination);DeviceLocator.verify(deviceID,latest);boolean changed=baseline==null||SyncPolicy.frameChanged(baseline,latest);SyncPolicy.Recovery recovery=SyncPolicy.recovery(baseline,latest,local,pending);byte[] pixels=changed||pending?DeskApi.base(destination):null;ui.post(()->{polling=false;if(destroyed||!foreground||busy||editing||resolvingConflict||editRevision.snapshot()!=revision||!origin.equals(destination))return;health.contacted(destination);if(recovery==SyncPolicy.Recovery.CONFLICT){automaticRetryAllowed=false;message="设备也有新内容，请重新读取并选择清单来源";updateStatus();return;}if(screenPending&&ScreenSync.acknowledged(cfg,latest)){screenPending=false;persist();}if(screenPending&&!sameProfile(baseline,latest)){automaticRetryAllowed=false;remote=latest;if(pixels!=null)base=pixels;message="屏幕配置也有更新，请核对后手动同步，未覆盖设备";updateStatus();return;}remote=latest;if(pixels!=null)base=pixels;if(recovery==SyncPolicy.Recovery.ACKNOWLEDGED){dirty=false;queuedSync=false;queuedFull=false;queuedInfo=false;editRevision.acknowledge(revision);health.received(destination);message="已确认设备保存成功";persist();redrawWhenIdle();}else if(recovery==SyncPolicy.Recovery.RETRY){if(latest.optBoolean("needs_full")){message="设备已重启，请明确应用布局后续传";updateStatus();}else if(automaticRetryAllowed&&SystemClock.elapsedRealtime()>=nextRetryAt){sync(false,false);}return;}else if(changed){tasks=DeskModel.copy(latest.optJSONArray("tasks"));adoptScreen(latest);persist();redrawWhenIdle();}if(message.equals("设备暂时离线，本机内容已保留")){message="已连接，内容保持同步";updateStatus();}long minute=System.currentTimeMillis()/60000;if(!dirty&&(!screenPending||automaticRetryAllowed)&&(minute!=lastClockMinute||screenPending&&DeskModel.layoutId(cfg).equals(remote.optString("layout_id")))&&remote.optString("layout_id").endsWith(".phone")&&!remote.optBoolean("needs_full")){lastClockMinute=minute;sync(false,false);}});}catch(Exception e){ui.post(()->{polling=false;if(!destroyed&&!busy){if(origin.equals(destination)){health.lastContact=0;connected=false;connectFailures++;nextConnectAt=SystemClock.elapsedRealtime()+SyncPolicy.retryDelay(connectFailures);}message="连接中断，正在找回屏幕；本机内容已保留";updateStatus();}});}});}ui.postDelayed(this,5000);}};
 void scheduleCheck(){ui.removeCallbacks(check);if(foreground)ui.postDelayed(check,5000);}
 @Override protected void onStart(){super.onStart();if(locator!=null)locator.resume();foreground=true;ReminderScheduler.reconcile(this,true);FocusAlarm.reconcile(this,true);if(!origin.isEmpty())scheduleCheck();}
 @Override protected void onSaveInstanceState(Bundle out){super.onSaveInstanceState(out);out.putString("historyQuery",records.query);out.putString("historyKind",records.kind);out.putString("captureDraft",capture.draft);out.putBoolean("captureAwaiting",capture.awaiting);out.putInt("setupStep",setup==null?0:setup.step);out.putString("page",page);out.putString("selectedScene",screen.selected);ArrayList<String> backPages=new ArrayList<>(),backSections=new ArrayList<>();for(String[] entry:backStack){backPages.add(entry[0]);backSections.add(entry[1]);}out.putStringArrayList("backPages",backPages);out.putStringArrayList("backSections",backSections);out.putString("infoSection",infoSection);out.putBoolean("showHistory",showHistory);out.putBoolean("showPreview",showPreview);out.putString("assistantDraft",assistant.draft);out.putString("assistantSection",assistant.section);out.putString("stagedLayout",stagedLayout);Bundle draft=new Bundle();for(Map.Entry<String,String> entry:drafts.entrySet())draft.putString(entry.getKey(),entry.getValue());out.putBundle("drafts",draft);}
 @Override protected void onActivityResult(int request,int result,android.content.Intent data){super.onActivityResult(request,result,data);if(integrations!=null)integrations.activityResult(request,result,data);}
 @Override public void onRequestPermissionsResult(int request,String[] permissions,int[] grants){super.onRequestPermissionsResult(request,permissions,grants);if(request==41){draw();}if(request==31){ReminderScheduler.reconcile(this,true);FocusAlarm.reconcile(this,true);draw();}if(request==21){for(int g:grants)if(g!=PackageManager.PERMISSION_GRANTED){message="蓝牙权限未授予，可手动填写地址";updateStatus();return;}if(grants.length>0)discovery.start();}}
 @Override protected void onStop(){super.onStop();foreground=false;if(discovery!=null)discovery.close();if(locator!=null)locator.close();ui.removeCallbacks(check);}
